args.command:
cd ~/captures && python3 -c "
from PIL import Image
for name in ['overview_001.jpg','side_002.jpg']:
    im = Image.open(name).convert('RGB')
    w,h = im.size
    px = im.load()
    yellow=[]; dark=[]
    for y in range(h):
        for x in range(w):
            r,g,b = px[x,y]
            if r>120 and g>100 and b<90 and (r-g)>20: yellow.append((x,y))
            if r<60 and g<60 and b<60: dark.append((x,y))
    def bbox(pts):
        if not pts: return None
        xs=[p[0] for p in pts]; ys=[p[1] for p in pts]
        return (min(xs),max(xs),min(ys),max(ys))
    print(name, 'size',w,h)
    print('  yellow', len(yellow), bbox(yellow))
    print('  dark', len(dark), bbox(dark))
"

